import sys
input = sys.stdin.read
data = input().split()

t = int(data[0])
index = 1

for _ in range(t):
    n, x = map(int, data[index].split())
    index += 1

    min_blows = float('inf')
    for _ in range(n):
        d, h = map(int, data[index].split())
        index += 1
        if d >= x:
            min_blows = min(min_blows, 1)
        elif d - h <= 0:
            continue
        else:
            min_blows = min(min_blows, (x - d) // (d - h) + 1 + ((x - d) % (d - h) != 0))

    if min_blows == float('inf'):
        print(-1)
    else:
        print(min_blows)
